    self.loading = False\\n        self.selection = ()\\n        self.original = []\\n        self.changes = {}\\n        self.description_seen = \\"\\"\\n        for name, variable in editor.vars.items():\\n            variable.trace_add(\\"write\\", lambda *_args, n=name: self.changed(n))\\n            if name == \\"task_template_id\\":\\n                continue\\n            widget = editor.widgets[name]\\n            if name in DROPDOWNS:\\n                widget.bind(\\"<<ComboboxSelected>>\\", lambda _e, n=name: self.changed(n), add=\\"+\\")\\n            else:\\n                widget.bind(\\"<FocusIn>\\", lambda _e, n=name: self.focus(n), add=\\"+\\")\\n                widget.bind(\\"<ButtonRelease-1>\\", lambda _e, n=name: self.focus(n), add=\\"+\\")\\n        editor.description.bind(\\"<<Modified>>\\", self.description_modified, add=\\"+\\")\\n        editor.description.bind(\\"<FocusIn>\\", lambda _e: self.focus(\\"description\\"), add=\\"+\\")\\n        editor.description.bind(\\"<ButtonRelease-1>\\", lambda _e: self.focus(\\"description\\"), add=\\"+\\")\\n\\n    def same_session(self, selected):\\n        return self.active and tuple(selected) == self.selection and self.editor.loaded_rows == self.original\\n\\n    def refresh_choices(self, multiple):\\n        for name in DROPDOWNS & set(self.editor.vars):\\n            values = (\\"TRUE\\", \\"FALSE\\") if name in BOOLEANS else tuple(self.editor.choices(name))\\n            if multiple:\\n                values = tuple(dict.fromkeys((\\"\\",) + tuple(values)))\\n            self.editor.widgets[name].configure(values=values, state=\\"readonly\\")\\n\\n    def begin(self, selected, force=False):\\n        if not force and self.same_session(selected):\\n            return\\n        selected = tuple(selected)\\n        by_id = {row[\\"task_template_id\\"]: row for row in self.editor.loaded_rows}\\n        if len(selected) < 2 or len(selected) != len(set(selected)) or any(key not in by_id for key in selected):\\n            raise ValueError(\\"Selection no longer matches the task draft. Reselect the rows.\\")\\n        self.active = False\\n        self.loading = True\\n        try:\\n            self.selection = selected\\n            self.original = [dict(row) for row in self.editor.loaded_rows]\\n            rows = [by_id[key] for key in selected]\\n            self.changes = {}\\n            set_form_state(self.editor, False)\\n            self.refresh_choices(True)\\n            for name, variable in self.editor.vars.items():\\n                variable.set(selection_display(rows, name, show_common=True))\\n            self.editor.widgets[\\"task_template_id\\"].configure(state=\\"disabled\\")\\n            self.editor.description.configure(state=\\"normal\\")\\n            text = selection_display(rows, \\"description\\", show_common=True)\\n            self.editor.description.delete(\\"1.0\\", \\"end\\")\\n            self.editor.description.insert(\\"1.0\\", text)\\n            self.description_seen = self.editor.description.get(\\"1.0\\", \\"end-1c\\")\\n            self.editor.description.edit_modified(False)\\n            self.active = True\\n        finally:\\n            self.loading = False\\n        self.editor._set_status(f\\"{len(selected)} templates selected - edit fields, then Apply to List. Untouched fields are preserved.\\")\\n\\n    def end(self):\\n        self.active = False\\n        self.changes = {}\\n        self.selection = ()\\n        self.original = []\\n        self.refresh_choices(False)\\n\\n    def changed(self, name):\\n        if not self.active or self.loading or name == \\"task_template_id\\":\\n            return\\n        self.changes[name] = self.editor.vars[name].get()\\n        self.note_changes()\\n\\n    def note_changes(self):\\n        self.editor._set_status(f\\"{len(self.selection)} templates selected; {len(self.changes)} edited field(s) ready for Apply to List.\\")\\n\\n    def description_modified(self, _event=None):\\n        widget = self.editor.description\\n        if not widget.edit_modified():\\n            return\\n        widget.edit_modified(False)\\n        self.flush_description()\\n\\n    def flush_description(self):\\n        current = self.editor.description.get(\\"1.0\\", \\"end-1c\\")\\n        if self.active and not self.loading and current != self.description_seen:\\n            self.changes[\\"description\\"] = current\\n            self.note_changes()\\n        self.description_seen = current\\n\\n    def focus(self, name):\\n        if not self.active or name in self.changes or name == \\"task_template_id\\":\\n            return\\n        widget = self.editor.description if name == \\"description\\" else self.editor.widgets[name]\\n        def select_placeholder():\\n            if not self.active or name in self.changes:\\n                return\\n            value = self.editor.description.get(\\"1.0\\", \\"end-1c\\") if name == \\"description\\" else self.editor.vars[name].get()\\n            if value != MULTIPLE_VALUES:\\n                return\\n            if name == \\"description\\":\\n                widget.tag_add(\\"sel\\", \\"1.0\\", \\"end-1c\\")\\n                widget.mark_set(\\"insert\\", \\"end-1c\\")\\n            else:\\n                widget.selection_range(0, \\"end\\")\\n                widget.icursor(\\"end\\")\\n        widget.after_idle(select_placeholder)\\n\\n    def apply(self):\\n        self.flush_description()\\n        if not self.active:\\n            raise ValueError(\\"Select the task rows before editing.\\")\\n        if tuple(self.editor.tree.selection()) != self.selection or self.editor.loaded_rows != self.original:\\n            raise ValueError(\\"Task draft or selection changed. Reselect rows before applying.\\")\\n        if not self.changes:\\n            self.editor._set_status(\\"No deliberately edited fields. Task draft unchanged.\\")\\n            return False\\n        changes = dict(self.changes)\\n        allowed = set(self.editor.vars) | {\\"description\\"}\\n        for name, value in changes.items():\\n            if name not in allowed or name == \\"task_template_id\\":\\n                raise ValueError(\\"Task identity fields cannot be batch-edited.\\")\\n            if not isinstance(value, str) or value.strip() == MULTIPLE_VALUES:\\n                raise ValueError(\\"Placeholder text cannot be applied as task data.\\")\\n        candidate = [dict(row) for row in self.original]\\n        priorities = set(self.editor.choices(\\"priority\\"))\\n        capabilities = set(self.editor.choices(\\"capability_id\\"))\\n        families = set(self.editor.choices(\\"target_family_id\\"))\\n        for row in candidate:\\n            if row[\\"task_template_id\\"] not in self.selection:\\n                continue\\n            row.update({name: value.strip() for name, value in changes.items()})\\n            if not re.fullmatch(r\\"[A-Z][A-Z0-9_]*\\", row[\\"task_template_id\\"]):\\n                raise ValueError(\\"Invalid task identity in draft.\\")\\n            problems = schema.errors(row, priorities)\\n            if row.get(\\"capability_id\\") and row[\\"capability_id\\"] not in capabilities:\\n                problems.append(\\"unknown capability_id\\")\\n            if row.get(\\"target_family_id\\", \\"\\") not in families:\\n                problems.append(\\"unknown LOCATION station family\\")\\n            if problems:\\n                raise ValueError(row[\\"task_template_id\\"] + \\": \\" + \\"; \\".join(problems))\\n        keys = [row[\\"task_template_id\\"] for row in candidate]\\n        if len(keys) != len(set(keys)):\\n            raise ValueError(\\"Duplicate task IDs in draft.\\")\\n        self.editor._validate_rows(candidate)\\n        if tuple(self.editor.tree.selection()) != self.selection or self.editor.loaded_rows != self.original:\\n            raise ValueError(\\"Task draft changed during validation. No batch rows applied.\\")\\n        self.editor.loaded_rows = candidate\\n        self.editor.dirty = True\\n        for key in self.selection:\\n            row = next(row for row in candidate if row[\\"task_template_id\\"] == key)\\n            self.editor.tree.item(key, values=tuple(row[field] for field in self.editor.tree[\\"columns\\"]))\\n        count = len(self.selection)\\n        self.begin(self.selection, force=True)\\n        self.editor._set_status(f\\"Updated {count} task draft rows; {len(changes)} field(s). UNSAVED CHANGES.\\")\\n        return True\\n\\n\\ndef install_task_inline(editor):\\n    controller = getattr(editor, \\"_task_inline\\", None)\\n    if controller is None:\\n        controller = TaskInlineEditor(editor)\\n        editor._task_inline = controller\\n    return controller\\n\\n\\ndef end_task_inline(editor):\\n    controller = getattr(editor, \\"_task_inline\\", None)\\n    if controller is not None:\\n        controller.end()\\n\\n\\ndef apply_task_inline(editor):\\n    controller = getattr(editor, \\"_task_inline\\", None)\\n    try:\\n        if controller is None:\\n            raise ValueError(\\"Reselect multiple task rows before editing.\\")\\n        return controller.apply()\\n    except (OSError, UnicodeError, csv.Error, ValueError) as error:\\n        editor.app.log(f\\"Task Templates batch Apply blocked; draft retained: {error}\\")\\n        editor._set_status(\\"Batch Apply blocked: \\" + str(error).splitlines()[0] + \\" See Activity Log.\\")\\n        return False\\n", "tests/test_task_inline_bulk_edit.py": "import ast\\nimport copy\\nimport inspect\\nimport textwrap\\nimport unittest\\nfrom types import SimpleNamespace as NS\\nfrom unittest.mock import Mock\\n\\nimport doda_task_templates_editor as tasks\\nimport doda_task_inline_bulk_edit as inline\\n\\n\\nclass Variable:\\n    def __init__(self):\\n        self.value=\\"\\"\\n        self.callbacks=[]\\n    def get(self):\\n        return self.value\\n    def set(self,value):\\n        self.value=value\\n        for callback in self.callbacks:\\n            callback()\\n    def trace_add(self,mode,callback):\\n        self.callbacks.append(callback)\\n        return str(len(self.callbacks))\\n\\n\\nclass Widget:\\n    def __init__(self,state=\\"normal\\"):\\n        self.state=state\\n        self.values=()\\n        self.selection_range=Mock()\\n        self.icursor=Mock()\\n        self.bindings={}\\n    def cget(self,name):\\n        return self.state if name==\\"state\\" else self.values\\n    def configure(self,**kwargs):\\n        self.state=kwargs.get(\\"state\\",self.state)\\n        self.values=kwargs.get(\\"values\\",self.values)\\n    def bind(self,event,callback,**kwargs):\\n        self.bindings[event]=callback\\n    def after_idle(self,callback):\\n        callback()\\n\\n\\nclass Text(Widget):\\n    def __init__(self):\\n        super().__init__()\\n        self.text=\\"\\"\\n        self.modified=False\\n        self.tag_add=Mock()\\n        self.mark_set=Mock()\\n    def get(self,*args):\\n        return self.text\\n    def delete(self,*args):\\n        self.text=\\"\\"\\n        self.modified=True\\n    def insert(self,index,text):\\n        self.text=text\\n        self.modified=True\\n    def edit_modified(self,value=None):\\n        if value is not None:\\n            self.modified=bool(value)\\n        return self.modified\\n\\n\\nclass Tree:\\n    def __init__(self):\\n        self.selected=(\\"A\\",\\"B\\")\\n        self.item=Mock()\\n    def selection(self):\\n        return self.selected\\n    def __getitem__(self,name):\\n        return (\\"task_template_id\\",\\"display_name\\",\\"priority\\",\\"target_type\\",\\"loop_task\\")\\n    def selection_remove(self,*args):\\n        self.selected=()\\n    def selection_set(self,*args):\\n        self.selected=tuple(args)\\n\\n\\nclass TaskInlineBulkTests(unittest.TestCase):\\n    def setUp(self):\\n        self.editor=tasks.TaskTemplatesEditor.__new__(tasks.TaskTemplatesEditor)\\n        e=self.editor\\n        self.base=dict(task_template_id=\\"A\\",display_name=\\"One\\",description=\\"First\\",capability_id=\\"\\",priority=\\"NORMAL\\",target_type=\\"TERRITORY\\",target_family_id=\\"\\",loop_task=\\"FALSE\\",time_to_complete_minutes=\\"\\",reward_mode=\\"CONTINUOUS\\",payout_count=\\"0\\",sort_order=\\"1\\",active=\\"FALSE\\")\\n        e.loaded_rows=[dict(self.base),{**self.base,\\"task_template_id\\":\\"B\\",\\"display_name\\":\\"Two\\",\\"description\\":\\"Second\\",\\"sort_order\\":\\"2\\"},{**self.base,\\"task_template_id\\":\\"C\\",\\"display_name\\":\\"Three\\",\\"sort_order\\":\\"3\\"}]\\n        e.vars={name:Variable() for name in tasks.FIELDS if name!=\\"description\\"}\\n        e.widgets={name:Widget(\\"readonly\\" if name in inline.DROPDOWNS else \\"normal\\") for name in e.vars}\\n        e.description=Text()\\n        e.widgets[\\"description\\"]=e.description\\n        e.tree=Tree()\\n        e.dirty=False\\n        e.editing_id=None\\n        e._multi_selection=True\\n        e._set_status=Mock()\\n        e.app=NS(log=Mock())\\n        e._validate_rows=Mock()\\n        e.commit=Mock()\\n        e._render_draft=Mock()\\n        choices={\\"capability_id\\":[\\"\\",\\"CAP_TEST\\"],\\"priority\\":[\\"NORMAL\\",\\"HIGH\\"],\\"target_type\\":[\\"STATION\\",\\"TERRITORY\\",\\"MISSION_AREA\\"],\\"target_family_id\\":[\\"\\",\\"TECH_LAB\\"],\\"reward_mode\\":[\\"CONTINUOUS\\",\\"PERIODIC_LUMP_SUM\\"]}\\n        e.choices=lambda name:choices.get(name,[])\\n        self.controller=inline.install_task_inline(e)\\n        self.controller.begin(e.tree.selection())\\n\\n    def apply(self):\\n        return inline.apply_task_inline(self.editor)\\n\\n    def test_non_identity_fields_are_editable(self):\\n        self.assertEqual(self.editor.widgets[\\"task_template_id\\"].state,\\"disabled\\")\\n        self.assertEqual(self.editor.widgets[\\"display_name\\"].state,\\"normal\\")\\n        self.assertEqual(self.editor.description.state,\\"normal\\")\\n        self.assertEqual(self.editor.widgets[\\"active\\"].state,\\"readonly\\")\\n\\n    def test_common_values_are_visible(self):\\n        self.assertEqual(self.editor.vars[\\"priority\\"].get(),\\"NORMAL\\")\\n        self.assertEqual(self.editor.vars[\\"payout_count\\"].get(),\\"0\\")\\n        self.assertEqual(self.editor.vars[\\"active\\"].get(),\\"FALSE\\")\\n\\n    def test_mixed_values_use_placeholder(self):\\n        self.assertEqual(self.editor.vars[\\"display_name\\"].get(),\\"Multiple values\\")\\n        self.assertEqual(self.editor.description.get(),\\"Multiple values\\")\\n\\n    def test_all_blank_remains_blank(self):\\n        self.assertEqual(self.editor.vars[\\"capability_id\\"].get(),\\"\\")\\n        self.assertEqual(self.editor.vars[\\"time_to_complete_minutes\\"].get(),\\"\\")\\n\\n    def test_display_does_not_create_edits(self):\\n        self.assertEqual(self.controller.changes,{})\\n        self.assertFalse(self.editor.dirty)\\n\\n    def test_focus_entry_does_not_change_data(self):\\n        self.controller.focus(\\"display_name\\")\\n        self.editor.widgets[\\"display_name\\"].selection_range.assert_called_once_with(0,\\"end\\")\\n        self.assertEqual(self.controller.changes,{})\\n\\n    def test_focus_description_selects_placeholder_without_edit(self):\\n        self.controller.focus(\\"description\\")\\n        self.editor.description.tag_add.assert_called_once_with(\\"sel\\",\\"1.0\\",\\"end-1c\\")\\n        self.assertEqual(self.controller.changes,{})\\n\\n    def test_typing_tracks_only_the_changed_field(self):\\n        self.editor.vars[\\"display_name\\"].set(\\"New\\")\\n        self.assertEqual(self.controller.changes,{\\"display_name\\":\\"New\\"})\\n        self.assertFalse(self.editor.dirty)\\n\\n    def test_description_modified_event_tracks_text_only(self):\\n        self.editor.description.insert(\\"1.0\\",\\"New description\\")\\n        self.controller.description_modified()\\n        self.assertEqual(self.controller.changes,{\\"description\\":\\"New description\\"})\\n        self.assertFalse(self.editor.description.modified)\\n\\n    def test_programmatic_description_events_do_not_become_edits(self):\\n        self.controller.description_modified()\\n        self.assertEqual(self.controller.changes,{})\\n\\n    def test_last_description_edit_is_flushed_on_apply(self):\\n        self.editor.description.insert(\\"1.0\\",\\"New description\\")\\n        self.assertTrue(self.apply())\\n        self.assertEqual([row[\\"description\\"] for row in self.editor.loaded_rows], [\\"New description\\",\\"New description\\",\\"First\\"])\\n\\n    def test_untouched_apply_skips_validation(self):\\n        before=copy.deepcopy(self.editor.loaded_rows)\\n        self.assertFalse(self.apply())\\n        self.assertEqual(self.editor.loaded_rows,before)\\n        self.editor._validate_rows.assert_not_called()\\n\\n    def test_apply_changes_only_selected_field_and_rows(self):\\n        before=copy.deepcopy(self.editor.loaded_rows)\\n        self.editor.vars[\\"display_name\\"].set(\\"New\\")\\n        self.assertTrue(self.apply())\\n        for old,row in zip(before,self.editor.loaded_rows):\\n            for field in tasks.FIELDS:\\n                if row[\\"task_template_id\\"] in (\\"A\\",\\"B\\") and field==\\"display_name\\":\\n                    self.assertEqual(row[field],\\"New\\")\\n                else:\\n                    self.assertEqual(row[field],old[field])\\n        self.assertTrue(self.editor.dirty)\\n        self.editor.commit.assert_not_called()\\n\\n    def test_apply_reloads_common_display_without_new_edits(self):\\n        self.editor.vars[\\"display_name\\"].set(\\"New\\")\\n        self.assertTrue(self.apply())\\n        self.assertEqual(self.editor.vars[\\"display_name\\"].get(),\\"New\\")\\n        self.assertEqual(self.controller.changes,{})\\n        self.assertFalse(self.apply())\\n\\n    def test_boolean_edit_is_explicit_not_automatic_activation(self):\\n        self.editor.vars[\\"loop_task\\"].set(\\"TRUE\\")\\n        self.assertTrue(self.apply())\\n        self.assertEqual([r[\\"loop_task\\"] for r in self.editor.loaded_rows],[\\"TRUE\\",\\"TRUE\\",\\"FALSE\\"])\\n        self.assertEqual([r[\\"active\\"] for r in self.editor.loaded_rows],[\\"FALSE\\",\\"FALSE\\",\\"FALSE\\"])\\n\\n    def test_blank_field_accepts_new_value(self):\\n        self.editor.vars[\\"time_to_complete_minutes\\"].set(\\"10\\")\\n        self.assertTrue(self.apply())\\n        self.assertEqual([r[\\"time_to_complete_minutes\\"] for r in self.editor.loaded_rows],[\\"10\\",\\"10\\",\\"\\"])\\n\\n    def test_explicit_clear_of_optional_field(self):\\n        self.editor.loaded_rows[0][\\"time_to_complete_minutes\\"]=\\"10\\"\\n        self.controller.begin((\\"A\\",\\"B\\"),force=True)\\n        self.editor.vars[\\"time_to_complete_minutes\\"].set(\\"\\")\\n        self.assertTrue(self.apply())\\n        self.assertEqual(self.editor.loaded_rows[0][\\"time_to_complete_minutes\\"],\\"\\")\\n\\n    def test_required_description_clear_is_atomic(self):\\n        before=copy.deepcopy(self.editor.loaded_rows)\\n        self.editor.description.delete(\\"1.0\\",\\"end\\")\\n        self.assertFalse(self.apply())\\n        self.assertEqual(self.editor.loaded_rows,before)\\n        self.assertEqual(self.controller.changes,{\\"description\\":\\"\\"})\\n\\n    def test_invalid_integer_is_atomic(self):\\n        before=copy.deepcopy(self.editor.loaded_rows)\\n        self.editor.vars[\\"sort_order\\"].set(\\"1.5\\")\\n        self.assertFalse(self.apply())\\n        self.assertEqual(self.editor.loaded_rows,before)\\n        self.assertFalse(self.editor.dirty)\\n\\n    def test_invalid_boolean_is_atomic(self):\\n        before=copy.deepcopy(self.editor.loaded_rows)\\n        self.editor.vars[\\"loop_task\\"].set(\\"maybe\\")\\n        self.assertFalse(self.apply())\\n        self.assertEqual(self.editor.loaded_rows,before)\\n\\n    def test_placeholder_is_never_applied(self):\\n        self.editor.vars[\\"display_name\\"].set(\\"Multiple values\\")\\n        self.assertFalse(self.apply())\\n        self.assertEqual(self.editor.loaded_rows[0][\\"display_name\\"],\\"One\\")\\n\\n    def test_identity_trace_is_ignored_and_identity_injection_rejected(self):\\n        self.editor.vars[\\"task_template_id\\"].set(\\"NEW\\")\\n        self.assertEqual(self.controller.changes,{})\\n        self.controller.changes[\\"task_template_id\\"]=\\"NEW\\"\\n        self.assertFalse(self.apply())\\n        self.assertEqual([r[\\"task_template_id\\"] for r in self.editor.loaded_rows],[\\"A\\",\\"B\\",\\"C\\"])\\n\\n    def test_unknown_capability_is_atomic(self):\\n        self.editor.vars[\\"capability_id\\"].set(\\"MISSING\\")\\n        self.assertFalse(self.apply())\\n        self.assertEqual(self.editor.loaded_rows[0][\\"capability_id\\"],\\"\\")\\n\\n    def test_cross_field_validation_failure_on_one_row_blocks_all(self):\\n        self.editor.loaded_rows[1].update(active=\\"TRUE\\",capability_id=\\"CAP_TEST\\")\\n        self.controller.begin((\\"A\\",\\"B\\"),force=True)\\n        before=copy.deepcopy(self.editor.loaded_rows)\\n        self.editor.vars[\\"loop_task\\"].set(\\"TRUE\\")\\n        self.assertFalse(self.apply())\\n        self.assertEqual(self.editor.loaded_rows,before)\\n        self.editor._validate_rows.assert_not_called()\\n\\n    def test_full_candidate_validation_failure_keeps_prior_dirty_draft(self):\\n        self.editor.dirty=True\\n        before=copy.deepcopy(self.editor.loaded_rows)\\n        self.editor.vars[\\"display_name\\"].set(\\"New\\")\\n        self.editor._validate_rows.side_effect=ValueError(\\"project invalid\\")\\n        self.assertFalse(self.apply())\\n        self.assertEqual(self.editor.loaded_rows,before)\\n        self.assertTrue(self.editor.dirty)\\n        self.assertEqual(self.controller.changes,{\\"display_name\\":\\"New\\"})\\n\\n    def test_candidate_read_error_is_atomic(self):\\n        before=copy.deepcopy(self.editor.loaded_rows)\\n        self.editor.vars[\\"display_name\\"].set(\\"New\\")\\n        self.editor._validate_rows.side_effect=OSError(\\"read failed\\")\\n        self.assertFalse(self.apply())\\n        self.assertEqual(self.editor.loaded_rows,before)\\n\\n    def test_stale_selection_is_rejected(self):\\n        self.editor.vars[\\"display_name\\"].set(\\"New\\")\\n        self.editor.tree.selected=(\\"B\\",\\"C\\")\\n        self.assertFalse(self.apply())\\n        self.assertEqual(self.editor.loaded_rows[0][\\"display_name\\"],\\"One\\")\\n\\n    def test_stale_draft_is_not_overwritten(self):\\n        self.editor.vars[\\"display_name\\"].set(\\"New\\")\\n        self.editor.loaded_rows[0][\\"display_name\\"]=\\"External\\"\\n        self.assertFalse(self.apply())\\n        self.assertEqual(self.editor.loaded_rows[0][\\"display_name\\"],\\"External\\")\\n\\n    def test_change_during_validation_is_not_overwritten(self):\\n        self.editor.vars[\\"display_name\\"].set(\\"New\\")\\n        def validate(_rows):\\n            self.editor.loaded_rows[0][\\"display_name\\"]=\\"External\\"\\n        self.editor._validate_rows.side_effect=validate\\n        self.assertFalse(self.apply())\\n        self.assertEqual(self.editor.loaded_rows[0][\\"display_name\\"],\\"External\\")\\n        self.assertEqual(self.editor.loaded_rows[1][\\"display_name\\"],\\"Two\\")\\n\\n    def test_same_selection_keeps_pending_edits(self):\\n        self.editor.vars[\\"display_name\\"].set(\\"New\\")\\n        self.controller.begin((\\"A\\",\\"B\\"))\\n        self.assertEqual(self.controller.changes,{\\"display_name\\":\\"New\\"})\\n\\n    def test_revert_form_resets_inputs_not_draft(self):\\n        before=copy.deepcopy(self.editor.loaded_rows)\\n        self.editor.vars[\\"display_name\\"].set(\\"New\\")\\n        self.editor.revert()\\n        self.assertEqual(self.controller.changes,{})\\n        self.assertEqual(self.editor.loaded_rows,before)\\n        self.assertEqual(self.editor.vars[\\"display_name\\"].get(),\\"Multiple values\\")\\n\\n    def test_return_to_single_restores_values_and_protected_id(self):\\n        self.editor.tree.selected=(\\"B\\",)\\n        self.editor.on_select()\\n        self.assertFalse(self.controller.active)\\n        self.assertEqual(self.editor.vars[\\"display_name\\"].get(),\\"Two\\")\\n        self.assertEqual(self.editor.description.get(),\\"Second\\")\\n        self.assertEqual(self.editor.widgets[\\"task_template_id\\"].state,\\"disabled\\")\\n        self.assertEqual(self.editor.widgets[\\"active\\"].values,(\\"TRUE\\",\\"FALSE\\"))\\n\\n    def test_deselect_does_not_change_rows(self):\\n        before=copy.deepcopy(self.editor.loaded_rows)\\n        self.editor.tree.selected=()\\n        self.editor.on_select()\\n        self.assertFalse(self.controller.active)\\n        self.assertEqual(self.editor.loaded_rows,before)\\n\\n    def test_apply_keeps_multi_selection(self):\\n        self.editor.vars[\\"display_name\\"].set(\\"New\\")\\n        self.assertTrue(self.apply())\\n        self.assertEqual(self.editor.tree.selection(),(\\"A\\",\\"B\\"))\\n        self.editor._render_draft.assert_not_called()\\n        self.assertEqual(self.editor.tree.item.call_count,2)\\n\\n    def test_boolean_controls_are_dropdowns(self):\\n        tree=ast.parse(textwrap.dedent(inspect.getsource(tasks.TaskTemplatesEditor.build)))\\n        self.assertFalse(any(isinstance(node,ast.Attribute) and node.attr==\\"Checkbutton\\" for node in ast.walk(tree)))\\n\\n    def test_no_bulk_window_is_created(self):\\n        tree=ast.parse(inspect.getsource(inline))\\n        self.assertFalse(any(isinstance(node,ast.Attribute) and node.attr==\\"Toplevel\\" for node in ast.walk(tree)))\\n"}}')
root=Path(sys.argv[1]).resolve()
module=root / "tools" / "doda_content_workbench"
source=root / "data_authoring" / "source"
if not module.is_dir() or not source.is_dir():
    raise SystemExit("Project directories missing; nothing installed.")

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None

def guard():
    errors=[]
    for name,expected in payload["guards"].items():
        actual=sha(module / name)
        if actual != expected:
            errors.append(f"{name}: expected {expected}, actual {actual}")
    for name in payload["new_files"]:
        if (module / name).exists():
            errors.append(name + ": target already exists")
    if errors:
        raise RuntimeError("GUARD FAILED. Inspect current local files; do not bypass.\n" + "\n".join(errors))

try:
    guard()
except Exception as error:
    print(error)
    raise SystemExit(1)
csv_bytes={p.relative_to(source).as_posix():p.read_bytes() for p in source.rglob("*.csv")}
if not csv_bytes:
    raise SystemExit("No source CSVs found; nothing installed.")

def csv_guard():
    now={p.relative_to(source).as_posix():p.read_bytes() for p in source.rglob("*.csv")}
    if now != csv_bytes:
        changed=sorted(name for name in set(now) | set(csv_bytes) if now.get(name) != csv_bytes.get(name))
        raise RuntimeError("Source CSV changed during installation: " + ", ".join(changed))

stamp=datetime.now().strftime("%Y%m%d_%H%M%S") + "_" + uuid4().hex[:8]
backup=module / "backups" / ("v125b_inline_tasks_" + stamp)
backup.mkdir(parents=True)
originals={name:(module / name).read_bytes() for name in sorted(set(p[0] for p in payload["patches"]))}
for name,data in originals.items():
    dest=backup / "modified_files" / name
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_bytes(data)
for name,data in csv_bytes.items():
    dest=backup / "source_csv_snapshot" / name
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_bytes(data)
(backup / "source_manifest.json").write_text(json.dumps({name:hashlib.sha256(data).hexdigest() for name,data in csv_bytes.items()},indent=2),encoding="utf-8")
print("Backup and logs:",backup,flush=True)

def suite(label,minimum):
    env=dict(os.environ)
    env["PYTHONPATH"]=str(module) + os.pathsep + env.get("PYTHONPATH","")
    env["PYTHONDONTWRITEBYTECODE"]="1"
    done=subprocess.run([sys.executable,"-m","unittest","discover","-s",str(module / "tests"),"-p","test_*.py"],
        cwd=root,env=env,text=True,encoding="utf-8",errors="replace",stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=900)
    (backup / (label + ".log")).write_text(done.stdout,encoding="utf-8")
    print(done.stdout,flush=True)
    counts=re.findall(r"Ran (\d+) tests? in",done.stdout)
    count=int(counts[-1]) if counts else 0
    if done.returncode != 0 or count < minimum:
        raise RuntimeError(f"{label} failed: exit {done.returncode}, tests {count}, required >= {minimum}.")
    csv_guard()
    return count

def task_method(data,name):
    cls=next(n for n in ast.parse(data.decode("utf-8-sig")).body if isinstance(n,ast.ClassDef) and n.name=="TaskTemplatesEditor")
    return ast.dump(next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name==name),include_attributes=False)

written={}
try:
    baseline=suite("baseline",810)
    guard()
    candidates={}
    for name,data in originals.items():
        text=data.decode("utf-8-sig").replace("\r\n","\n")
        for target,old,new in payload["patches"]:
            if name != target:
                continue
            if text.count(old) != 1:
                raise RuntimeError("Content guard failed: " + name + ". Inspect current file.")
            text=text.replace(old,new)
        ast.parse(text)
        newline="\r\n" if b"\r\n" in data else "\n"
        encoded=text.replace("\n",newline).encode("utf-8")
        if data.startswith(b"\xef\xbb\xbf"):
            encoded=b"\xef\xbb\xbf" + encoded
        candidates[name]=encoded
    for name,text in payload["new_files"].items():
        ast.parse(text)
        candidates[name]=text.encode("utf-8")
    for name in ("commit","save","candidate_valid","_validate_rows","remove","revert_source","record"):
        if task_method(originals["doda_task_templates_editor.py"],name) != task_method(candidates["doda_task_templates_editor.py"],name):
            raise RuntimeError("Save/draft safeguard preservation check failed: " + name)
    guard()
    csv_guard()
    for name,data in candidates.items():
        path=module / name
        tmp=path.with_name("." + path.name + "." + uuid4().hex + ".tmp")
        try:
            tmp.write_bytes(data)
            if name in originals and path.read_bytes() != originals[name]:
                raise RuntimeError("File changed before write: " + name)
            if name not in originals and path.exists():
                raise RuntimeError("New target appeared before write: " + name)
            os.replace(tmp,path)
            written[name]=data
        finally:
            tmp.unlink(missing_ok=True)
    after=suite("post_install",baseline + 36)
    csv_guard()
    for name,data in written.items():
        if (module / name).read_bytes() != data:
            raise RuntimeError("Patched file changed during tests: " + name)
    for name,expected in payload["guards"].items():
        if name not in written and sha(module / name) != expected:
            raise RuntimeError("Unmodified guarded file changed: " + name)
    hashes={name:sha(module / name) for name in written}
    (backup / "installed_hashes.json").write_text(json.dumps(hashes,indent=2),encoding="utf-8")
    print(f"V125B INSTALLED: baseline {baseline}, post-install {after}; {len(csv_bytes)} source CSVs unchanged.")
    print("Task Templates inline multi-row Apply enabled. Description tracked; Boolean dropdowns added.")
    print("Save/draft validation and close/refresh policy preserved. Shared editors unchanged. Manual GUI check required.")
    print(json.dumps(hashes,indent=2))
except BaseException as error:
    failures=[]
    for name,data in reversed(list(written.items())):
        path=module / name
        try:
            if not path.is_file() or path.read_bytes() != data:
                raise RuntimeError("Current file differs from patch output; refusing to overwrite external edits.")
            if name in originals:
                tmp=path.with_name("." + path.name + ".rollback." + uuid4().hex)
                try:
                    tmp.write_bytes(originals[name])
                    os.replace(tmp,path)
                finally:
                    tmp.unlink(missing_ok=True)
                if path.read_bytes() != originals[name]:
                    raise RuntimeError("Rollback verification failed.")
            else:
                path.unlink()
        except Exception as rollback_error:
            failures.append(name + ": " + str(rollback_error))
    print("INSTALLATION STOPPED:",str(error))
    print("Patched files rolled back." if not failures else "ROLLBACK NEEDS INSPECTION:\n" + "\n".join(failures))
    try:
        csv_guard()
        print("Source CSVs unchanged.")
    except Exception as source_error:
        print(source_error)
        print("Source snapshot retained in backup. No CSV is overwritten automatically; inspect before restoration.")
    print("Backup and logs:",backup)
    raise SystemExit(1)

'@
$temporary = Join-Path $env:TEMP ('doda_v125b_' + [guid]::NewGuid().ToString('N') + '.py')
try {
    [IO.File]::WriteAllText($temporary, $code, (New-Object System.Text.UTF8Encoding($false)))
    & $python $temporary $Root
    if ($LASTEXITCODE -ne 0) { throw "v125b stopped with exit code $LASTEXITCODE. Inspect the reported log/backup before retrying." }
} finally {
    Remove-Item -LiteralPath $temporary -Force -ErrorAction SilentlyContinue
}
